            if show_why:
                required_by = reverse_deps(locked, locked_repository)
                required_by_length = max(
                    required_by_length, len(" from " + ",".join(required_by.keys()))
                )

    if self.option("format") == OutputFormats.JSON:
        packages = []

        for locked in locked_packages:
