def _update_user_details(
    user: User,
    oidc_key: str,
    user_email: str,
    user_first_name: str,
    user_last_name: str,
    sub: str,
    last_login: int | None,
) -> bool:
    user_sub = user.get_value_from_private_metadata(oidc_key)
    fields_to_save = set()
    if user_sub != sub:
        user.store_value_in_private_metadata({oidc_key: sub})
        fields_to_save.add("private_metadata")

    if user.email != user_email:
        if User.objects.filter(email=user_email).exists():
            logger.warning(
                "Unable to update user email as the new one already exists in DB",
                extra={"oidc_key": oidc_key},
            )
            return False
        user.email = user_email
        match_orders_with_new_user(user)
        fields_to_save.update({"email", "search_vector"})

    if last_login:
        if not user.last_login or user.last_login.timestamp() < last_login:
            login_time = datetime.datetime.fromtimestamp(last_login, tz=datetime.UTC)
            user.last_login = login_time
            fields_to_save.add("last_login")
    else:
        if (
            not user.last_login
            or (timezone.now() - user.last_login).seconds
            > settings.OAUTH_UPDATE_LAST_LOGIN_THRESHOLD
        ):
            user.last_login = timezone.now()
            fields_to_save.add("last_login")

    if user.first_name != user_first_name:
        user.first_name = user_first_name
        fields_to_save.update({"first_name", "search_vector"})

    if user.last_name != user_last_name:
        user.last_name = user_last_name
        fields_to_save.update({"last_name", "search_vector"})

    if not user.search_vector or "search_vector" in fields_to_save:
        update_user_search_vector(user, save=False)
        fields_to_save.add("search_vector")

    if not user.is_confirmed:
        user.is_confirmed = True

